export const EMOJIS=Object.freeze([
 ['smile','🙂','Smiling face'],['grin','😀','Big smile'],['laugh','😂','Laughing'],['love','🥰','Feeling loved'],['cool','😎','Cool'],['wink','😉','Wink'],['think','🤔','Thinking'],['sad','😢','Sad'],['cry','😭','Crying'],['angry','😡','Angry'],['sleep','😴','Sleepy'],['shock','😮','Surprised'],['thumbsup','👍','Thumbs up'],['thumbsdown','👎','Thumbs down'],['heart','❤️','Love'],['fire','🔥','Fire'],['party','🎉','Celebrate'],['poop','💩','Poop'],['coffee','☕','Coffee'],['wave','👋','Hello'],['pray','🙏','Thank you'],['strong','💪','You got this'],['check','✅','Done'],['sparkle','✨','Sparkles'],
].map(([id,value,label])=>({id,value,label})));
const byId=new Map(EMOJIS.map(e=>[e.id,e])),matches=[...EMOJIS,{...byId.get('heart'),value:'❤'}].sort((a,b)=>b.value.length-a.value.length);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function emojiTokens(text){const result=[];let plain='',i=0;while(i<text.length){const found=matches.find(e=>text.startsWith(e.value,i));if(found){if(plain)result.push({text:plain});plain='';result.push({emoji:found.id});i+=found.value.length;if(text[i]==='\ufe0f')i++;}else{const c=String.fromCodePoint(text.codePointAt(i));plain+=c;i+=c.length;}}if(plain)result.push({text:plain});return result;}
export function richHtml(text){return emojiTokens(text).map(t=>t.text!==undefined?esc(t.text):`<canvas class="inline-emoji" data-emoji="${t.emoji}" width="16" height="16" role="img" aria-label="${byId.get(t.emoji).label}" title="${byId.get(t.emoji).value}"></canvas>`).join('');}
export function drawEmoji(c,id,x=0,y=0,size=16){c.imageSmoothingEnabled=false;const s=size/16,r=(a,b,w,h,col)=>{c.fillStyle=col;c.fillRect(Math.round(x+a*s),Math.round(y+b*s),Math.ceil(w*s),Math.ceil(h*s));},bitmap=(rows,col,ox=0,oy=0)=>rows.forEach((row,j)=>[...row].forEach((v,i)=>{if(v!==' ')r(i+ox,j+oy,1,1,col);}));
 const brown='#69543b',yellow='#f2ca64',red='#d87367',blue='#7faec1',cream='#fff1c9';
 if(['smile','grin','laugh','love','cool','wink','think','sad','cry','angry','sleep','shock'].includes(id)){
  bitmap(['     ######     ','   ##########   ','  ############  ',' ############## ',' ############## ','################','################','################','################','################','################',' ############## ',' ############## ','  ############  ','   ##########   ','     ######     '],id==='angry'?'#df9b69':yellow);r(4,2,7,1,'#f9df8f');
  if(id==='cool'){r(2,5,5,4,brown);r(9,5,5,4,brown);r(7,5,2,1,brown);r(3,6,2,1,'#a0b8ad');r(10,6,2,1,'#a0b8ad');}else if(id==='love'){for(const dx of [2,9])bitmap(['# #','###','###',' # '],red,dx,5);}else if(['laugh','sleep'].includes(id)){r(3,6,3,1,brown);r(10,6,3,1,brown);}else{r(4,5,2,3,brown);r(10,5,id==='wink'?3:2,id==='wink'?1:3,brown);}
  if(['sad','cry'].includes(id)){r(5,11,6,1,brown);r(4,12,1,1,brown);r(11,12,1,1,brown);r(3,8,2,id==='cry'?6:3,blue);if(id==='cry')r(11,8,2,6,blue);}else if(['shock','sleep'].includes(id)){r(6,10,4,4,brown);r(7,11,2,2,'#ab7350');}else if(['grin','laugh'].includes(id)){r(4,9,8,4,brown);r(5,9,6,1,cream);r(6,12,4,1,red);if(id==='laugh'){r(1,7,2,4,blue);r(13,7,2,4,blue);}}else{r(4,10,2,1,brown);r(6,11,5,1,brown);r(11,9,1,2,brown);}
  if(id==='angry'){r(3,3,4,1,brown);r(9,3,4,1,brown);r(6,4,1,1,brown);r(9,4,1,1,brown);}if(id==='think'){r(8,12,6,3,'#d6a953');r(12,9,2,5,'#d6a953');}return;
 }
 if(id==='heart'){bitmap([' ## ## ','#######','#######','#######',' ##### ','  ###  ','   #   '],red,4,5);r(5,6,2,1,'#f2b09b');return;}
 if(id==='poop'){bitmap(['       ##       ','      ####      ','     ######     ','    ########    ','   ##########   ','    ########    ','  ############  ',' ############## ',' ############## ','  ############  '],'#a9855b',0,4);r(4,9,3,2,cream);r(9,9,3,2,cream);r(5,9,1,2,brown);r(10,9,1,2,brown);r(6,12,4,1,cream);return;}
 if(id==='coffee'){r(3,6,9,7,cream);r(12,7,3,4,'#c9ae7f');r(13,8,1,2,'#eef0dc');r(3,5,9,2,'#977350');r(2,13,12,1,'#b8c3a0');r(5,1,1,3,'#c1d2bd');r(9,2,1,2,'#c1d2bd');return;}
 if(id==='fire'){bitmap(['       #        ','       ##       ','      ###       ','     #####      ','   ########     ','   #########    ','  ###########   ',' ############   ',' ############   ','  ##########    ','   ########     '],'#d99b54',0,3);bitmap(['   #  ','  ### ',' #####',' #####','  ### '],yellow,5,9);return;}
 if(id==='check'){r(1,2,14,13,'#89ab77');bitmap(['      ##','     ## ','#   ##  ','## ##   ',' ###    ','  #     '],cream,4,6);return;}
 if(id==='thumbsup'||id==='thumbsdown'){c.save();if(id==='thumbsdown'){c.translate(x+size,y+size);c.rotate(Math.PI);drawEmoji(c,'thumbsup',0,0,size);c.restore();return;}r(2,8,3,7,'#85a7a8');r(6,6,8,8,yellow);r(7,2,3,6,yellow);r(6,14,7,1,'#d1a756');r(13,8,2,5,yellow);r(7,7,6,1,'#f8dfa0');c.restore();return;}
 if(id==='pray'){for(const dx of [3,9]){r(dx,8,4,7,'#89a9b3');r(dx+1,3,2,8,yellow);}r(7,3,2,9,'#e9ba5a');return;}
 if(id==='strong'){r(2,10,12,4,yellow);r(2,6,4,6,yellow);r(3,3,6,4,yellow);r(7,9,6,3,'#d2a253');return;}
 if(id==='wave'){r(5,7,7,7,yellow);for(let i=0;i<4;i++)r(3+i*3,2+(i%2),2,8,yellow);r(2,8,3,4,yellow);r(13,1,2,2,'#96b49b');r(1,3,1,3,'#96b49b');return;}
 if(id==='party'){bitmap(['      #','     ##','    ###','   ####','  #####',' ######','#######'],'#c49ab8',3,7);for(const [a,b,col]of [[2,2,red],[7,1,blue],[12,3,yellow],[9,6,red],[13,8,blue]])r(a,b,2,2,col);return;}
 for(const [a,b]of [[5,3],[11,9]]){r(a,b-2,1,5,yellow);r(a-2,b,5,1,yellow);r(a-1,b-1,3,3,yellow);}
}
export function paintEmojiCanvases(root=document){root.querySelectorAll('canvas[data-emoji]').forEach(canvas=>{const c=canvas.getContext('2d');c.clearRect(0,0,canvas.width,canvas.height);drawEmoji(c,canvas.dataset.emoji,0,0,16);});}
export function initEmojiPicker(){const picker=document.querySelector('#emoji-picker'),toggle=document.querySelector('#emoji-toggle'),input=document.querySelector('#community-text');document.querySelector('#emoji-grid').innerHTML=EMOJIS.map(e=>`<button type="button" data-pick-emoji="${e.id}" aria-label="${e.label}" title="${e.label}"><canvas data-emoji="${e.id}" width="16" height="16" aria-hidden="true"></canvas></button>`).join('');paintEmojiCanvases();
 const close=()=>{picker.classList.add('hidden');toggle.setAttribute('aria-expanded','false');};toggle.onclick=()=>{const open=picker.classList.toggle('hidden')===false;toggle.setAttribute('aria-expanded',String(open));if(open)picker.querySelector('[data-pick-emoji]').focus();};document.querySelector('#emoji-close').onclick=close;picker.addEventListener('keydown',event=>{const buttons=[...picker.querySelectorAll('[data-pick-emoji]')],index=buttons.indexOf(document.activeElement),step={ArrowRight:1,ArrowLeft:-1,ArrowDown:6,ArrowUp:-6}[event.key];if(index>=0&&step){event.preventDefault();buttons[(index+step+buttons.length)%buttons.length].focus();}});picker.addEventListener('click',event=>{const button=event.target.closest('[data-pick-emoji]');if(!button||input.disabled)return;const value=byId.get(button.dataset.pickEmoji).value,a=input.selectionStart??input.value.length,b=input.selectionEnd??a;if(input.value.length-(b-a)+value.length>input.maxLength)return;input.setRangeText(value,a,b,'end');input.dispatchEvent(new Event('input',{bubbles:true}));input.focus({preventScroll:true});close();});document.addEventListener('click',event=>{if(!picker.contains(event.target)&&!toggle.contains(event.target))close();});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!picker.classList.contains('hidden')){close();toggle.focus();}});return close;
}
export function bubbleRows(c,text,maxWidth=205){const chars=emojiTokens(text).flatMap(t=>t.emoji?[{emoji:t.emoji,width:16}]:[...t.text].map(ch=>({text:ch,width:c.measureText(ch).width})));const rows=[{tokens:[],width:0}];for(const token of chars){let row=rows.at(-1);if(row.width+token.width>maxWidth){if(rows.length===3){row.tokens.push({text:'…',width:10});row.width+=10;break;}rows.push({tokens:[],width:0});row=rows.at(-1);}row.tokens.push(token);row.width+=token.width;}return rows;}
export function paintBubbleRow(c,row,x,y){for(const t of row.tokens){if(t.emoji)drawEmoji(c,t.emoji,x,y-13,15);else c.fillText(t.text,x,y);x+=t.width;}}
